/**
# 读取rojo路径

本项目可以读取指定 rojo 配置文件, 获取一个字典.

该字典表达了真实路径与roblox实例路径的对应关系.

字典的key为真实路径, 比如 "src/Confidentials"

字典的value为该路径同步到roblox后, 其实例路径, 比如 "game.ServerStorage/Confidentials"



本项目一个库, 接收参数为 rojo 文件路径, 返回一个对象, 提供以下方法:

* GetRbxPath(realPath) 方法, 接收一个真实路径, 返回该路径对应的 roblox 实例路径.
该方法首先将 realPath 转为 '/' 分割, 然后遍历缓存字典, 找到与其匹配字符串最多的那一项, 作为其 roblox 路径开头, 然后再将剩余部分以 `.` 分割, 作为 roblox 路径的剩余部分.
 */

const fs = require('fs');
const path = require('path');


var _robloxPathDict

/**
 * 读取Rojo配置文件并返回路径映射
 * @param {string} rojoConfigPath - Rojo配置文件的路径
 * @returns {Object} - 包含真实路径到Roblox实例路径的映射
 */
function getRojoPaths(rojoConfigPath) {
    // 读取Rojo配置文件
    const rojoConfig = JSON.parse(fs.readFileSync(rojoConfigPath, 'utf8'));

    // 初始化结果对象
    const pathMapping = {};

    // 递归函数，用于遍历Rojo配置
    function traverseRojoTree(node, currentPath, robloxPath) {

        // if node is not an object, skip it
        if (typeof node !== 'object' || node === null) {
            return;
        }


        if (robloxPath == "game.ReplicatedStorage.Packages") {
            const fullPath = node["$path"];
            // assert fullPath exist
            if (!fs.existsSync(fullPath)) {
                throw new Error(`已配置"Packages"节点, 但${fullPath} 不存在`)
            }

            // 遍历fullPath下的所有文件夹, 如果包含 default.project.json, 则读取其 "name" 和 "tree.$path" 节点 
            const packages = fs.readdirSync(fullPath);
            for (const package of packages) {


                const packagePath = path.join(fullPath, package);
                var subRojoConfigPath = path.join(packagePath, "default.project.json")
                if (!fs.existsSync(subRojoConfigPath)) {
                    continue;
                }

                const projectJson = JSON.parse(fs.readFileSync(path.join(packagePath, "default.project.json"), 'utf8'));

                var packagePathSrc = path.join(fullPath, package, projectJson.tree.$path)
                var packageName = projectJson.name
                // trim `init.lua`, `init2.lua` from full path
                // 移除 `init.lua` 或 `init2.lua` 后缀
                const trimmedPath = packagePathSrc.replace(/\/init2?\.lua$/, '').replace(/\\/g, '/');
                // 更新映射
                pathMapping[trimmedPath] = `game.ReplicatedStorage.Packages.${packageName}`;
            }
        }

        if (node["$path"]) {
            const fullPath = node["$path"];
            // trim `init.lua`, `init2.lua` from full path
            // 移除 `init.lua` 或 `init2.lua` 后缀
            const trimmedPath = fullPath.replace(/\/init2?\.lua$/, '');
            // 更新映射
            pathMapping[trimmedPath] = robloxPath;
        }

        // 遍历节点的所有属性
        for (const [childName, childNode] of Object.entries(node)) {


            // 跳过特殊属性
            if (childName.startsWith('$')) continue;

            // 递归遍历子节点
            traverseRojoTree(childNode, path.join(currentPath, childName), `${robloxPath}.${childName}`);
        }
    }

    // 遍历Rojo配置中的树结构
    for (const [treeName, treeNode] of Object.entries(rojoConfig.tree)) {
        traverseRojoTree(treeNode, '', `game.${treeName}`);
    }

    return pathMapping;
}

/**
 * 将真实路径转换为Roblox实例路径
 * @param {string} realPath - 真实文件系统路径
 * @returns {string} - 对应的Roblox实例路径
 */
function getRbxPath(realPath) {

    // 将路径转换为统一格式
    realPath = realPath.replace(/\\/g, '/');


    // if realPath ends with '/init.lua', remove it
    if (realPath.endsWith('/init.lua')) {
        realPath = realPath.slice(0, -9);
    }

    let bestMatch = '';
    let bestMatchLength = 0;

    // 遍历pathMapping，找到最佳匹配
    for (const [mappedPath, rbxPath] of Object.entries(_robloxPathDict)) {
        if (realPath.startsWith(mappedPath) && mappedPath.length > bestMatchLength) {
            bestMatch = rbxPath;
            bestMatchLength = mappedPath.length;
        }
    }
    if (bestMatch) {
        // 移除文件名后缀
        const realPathWithoutExtension = realPath.replace(".luau", '').replace(".lua", '').replace(".json", '');

        // 移除匹配的部分，并将剩余部分转换为Roblox路径格式
        const remainingPath = realPathWithoutExtension.slice(bestMatchLength);

        var rojoPath = bestMatch;

        if (remainingPath == "" || remainingPath == undefined) {
        } else {
            // split remainingPath by '/'
            var remainingPathParts = remainingPath.split('/');
            // for each part, add it to rojoPath
            for (const part of remainingPathParts) {
                if (part == "") {
                    continue
                }
                if (part.includes('.')) {
                    rojoPath += `["${part}"]`;
                }
                else {
                    rojoPath += "." + part;
                }
            }
        }



        // 特殊处理 Packages 路径, 去除 __ 
        // 对于 Packages 目录下的文件, 会多一层结构, 默认为 'src' 目录, 需要替换掉
        if (rojoPath.includes("game.ReplicatedStorage.Packages")) {
            rojoPath = rojoPath.replace('.src.', '.')
            rojoPath = rojoPath.replace('.src[', '[')
            rojoPath = rojoPath.replace("__", '');
        }

        return rojoPath;
    } else {
        var fullPath = path.resolve(realPath);
        throw new Error(`没有在 rojo 配置中找到匹配的路径: ${fullPath}`)
    }

    // 如果没有匹配，返回原始路径（移除文件名后缀）
    return realPath.replace(/\.[^.]+$/, '');
}



module.exports = {
    init: function (rojoConfigPath) {
        _robloxPathDict = getRojoPaths(rojoConfigPath);
    },
    getRbxPath
};
